# China Southern postal code ranges (prefix 2-digit)
CHINA_SOUTHERN_RANGES = [
    {"start": 51, "end": 53},  # Guangdong
    {"start": 35, "end": 36},  # Fujian
]


def is_china_southern(postal_code: str) -> bool:
    """Cek apakah kode pos China masuk area Southern (Guangdong/Fujian)."""
    if not postal_code:
        return False
    digits = "".join(c for c in postal_code if c.isdigit())
    if len(digits) < 2:
        return False
    prefix2 = int(digits[:2])
    return any(r["start"] <= prefix2 <= r["end"] for r in CHINA_SOUTHERN_RANGES)


def find_country(name: str) -> dict:
    """
    Lookup zone data untuk satu negara.
    Return dict dari ZONE_INDEX, atau raise UPSZoneError.
    """
    key = name.strip().lower()

    if key in ZONE_INDEX:
        return ZONE_INDEX[key]

    # Fuzzy: cari yang mengandung key
    matches = {k: v for k, v in ZONE_INDEX.items() if key in k or k in key}
    if len(matches) == 1:
        return list(matches.values())[0]
    if len(matches) > 1:
        names = ", ".join(matches.keys())
        raise UPSZoneError(f"Negara '{name}' ambigu, cocok dengan: {names}")

    raise UPSZoneError(
        f"Negara '{name}' tidak ditemukan di UPS Zone Index. "
        f"Periksa ejaan atau tambahkan alias."
    )


def get_zone(country: str, direction: str, service: str, postal_code: str = None) -> int:
    """
    Dapatkan zone (int 1-10) untuk kombinasi negara/direction/service.

    service: "saver" | "expedited" | "wwef"
    direction: "export" | "import"

    Return None jika service tidak tersedia untuk negara ini.
    Raise UPSZoneError jika negara tidak ditemukan.
    """
    # Handle China Southern
    effective_country = country
    if country.lower().strip() == "china" and postal_code:
        if is_china_southern(postal_code):
            effective_country = "cn southern"

    cdata = find_country(effective_country)

    key_map = {
        ("export", "saver"):      "saverExport",
        ("export", "expedited"):  "expeditedExport",
        ("export", "wwef"):       "wwefExport",
        ("import", "saver"):      "saverImport",
        ("import", "expedited"):  "expeditedImport",
        ("import", "wwef"):       "wwefImport",
    }

    field = key_map.get((direction, service))
    if field is None:
        raise UPSZoneError(f"Kombinasi direction='{direction}' service='{service}' tidak valid.")

    zone = cdata.get(field)

    # WWEF fallback ke saver zone jika wwef zone kosong
    if zone is None and service == "wwef":
        fallback_field = "saverExport" if direction == "export" else "saverImport"
        zone = cdata.get(fallback_field)

    return zone  # bisa None kalau memang tidak available
